from pathlib import Path
import json,html,collections
root=Path(__file__).resolve().parent.parent/'docs'
p=json.loads((root/'proposal.json').read_text())
c=json.loads((root/'feature-catalog.json').read_text())
features=c['features']
counts=collections.Counter(f['phase'] for f in features)
category_counts=collections.Counter(f['category'] for f in features)
e=lambda x:html.escape(str(x),quote=True)
def link(url,label):return '<a href="'+e(url)+'" target="_blank" rel="noopener noreferrer">'+e(label)+'</a>'
benchmarks=''.join('<tr><th>'+e(b['name'])+'</th><td>'+e(b['deployment'])+'</td><td>'+e(b['focus'])+'<p class="subtle">'+e(b['qualification'])+'</p></td><td>'+link(b['url'],'Primary source')+(('<br>'+link(b['secondaryUrl'],'Additional source')) if b.get('secondaryUrl') else '')+'</td></tr>' for b in p['benchmarks'])
phases=''.join('<article class="phase-card" id="phase-'+e(ph['id'])+'"><div class="phase-top"><span class="phase-id">'+e(ph['id'])+'</span><span>'+str(counts[ph['id']])+' candidate features</span></div><h3>'+e(ph['name'])+'</h3><p class="release">'+e(ph['release'])+'</p><p>'+e(ph['deliverables'])+'</p><div class="gate"><strong>Acceptance gate</strong><p>'+e(ph['gate'])+'</p></div><button class="phase-filter" data-phase="'+e(ph['id'])+'">Explore '+e(ph['id'])+' features →</button></article>' for ph in p['phases'])
architecture=''.join('<div class="architecture-node"><strong>'+e(a['component'])+'</strong><p>'+e(a['responsibility'])+'</p></div>' for a in p['architecture'])
kickoff=''.join('<li>'+e(x)+'</li>' for x in p['kickoff'])
principles=''.join('<li>'+e(x)+'</li>' for x in p['principles'])
gaps=''.join('<li>'+e(x)+'</li>' for x in p['knownEasiGaps'])
notes=''.join('<li>'+e(x)+'</li>' for x in p['scopeNotes'])
options=''.join('<option value="'+e(ph['id'])+'">'+e(ph['id']+' · '+ph['name'])+'</option>' for ph in p['phases'])
category_options=''.join('<option>'+e(cat)+'</option>' for cat in category_counts)
data=json.dumps(features,ensure_ascii=False).replace('<','\\u003c')
source_urls=sorted(set(url for f in features for url in f['references']) | set(p['architectureSources']) | set(b['url'] for b in p['benchmarks']) | set(b['secondaryUrl'] for b in p['benchmarks'] if b.get('secondaryUrl')))
sources=''.join('<li>'+link(url,url)+'</li>' for url in source_urls)
page='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="EASI View competitive feature catalog, implementation phases and architecture proposal."><title>easi-view · Feature catalog and roadmap</title>
<style>
:root{--paper:#faf9f6;--white:#fff;--ink:#182c2b;--muted:#576561;--green:#176b56;--line:#dce1d7;--mono:Consolas,'SFMono-Regular',monospace}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:15px/1.7 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}a{color:var(--green);text-underline-offset:3px}button,input,select{font:inherit}button{cursor:pointer}main,header,nav{max-width:1220px;margin:auto;padding:0 30px}header{padding-top:55px;padding-bottom:38px}.eyebrow{color:var(--green);font:11px/1.7 var(--mono);letter-spacing:.06em}h1{font-size:clamp(35px,5vw,58px);line-height:1.1;letter-spacing:-.05em;margin:20px 0}h1 span{color:var(--green)}header>p{max-width:870px;color:var(--muted);font-size:18px}.stats{display:flex;flex-wrap:wrap;gap:15px;margin-top:26px}.stat{padding:12px 18px;border:1px solid var(--line);border-radius:7px;background:var(--white)}.stat strong{color:var(--green);font-size:24px;margin-right:9px}nav{display:flex;gap:23px;flex-wrap:wrap;padding-top:20px;padding-bottom:20px;border-block:1px solid var(--line);font-size:13px}nav a{text-decoration:none;font-weight:600}section{padding:48px 0;border-bottom:1px solid var(--line)}h2{margin:0 0 18px;font-size:30px;letter-spacing:-.04em;line-height:1.2}h3{font-size:19px;line-height:1.3;letter-spacing:-.02em}.intro{max-width:910px;color:var(--muted)}.callout{border-left:3px solid var(--green);padding:15px 19px;background:#eff4ec;border-radius:0 5px 5px 0;margin:20px 0}.callout p{margin:0}.architecture{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:23px 0}.architecture-node{padding:19px;background:var(--white);border:1px solid var(--line);border-radius:7px;font-size:13px}.architecture-node strong{color:var(--green)}.architecture-node p{margin-bottom:0;color:var(--muted)}.table-scroll{overflow:auto;border:1px solid var(--line);border-radius:7px;margin-top:24px}table{border-collapse:collapse;width:100%;background:var(--white);font-size:13px;min-width:790px}th,td{padding:15px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}thead th{background:#eff4ec;font-size:11px}tbody th{min-width:130px}.subtle{color:var(--muted);font-size:12px;margin:8px 0 0}.phase-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:23px 0}.phase-card{padding:23px;background:var(--white);border:1px solid var(--line);border-radius:8px;min-width:0}.phase-top{display:flex;align-items:center;justify-content:space-between;gap:15px;font:10px/1.5 var(--mono);color:var(--muted)}.phase-id{color:var(--green);background:#eff4ec;border-radius:4px;padding:6px 10px;font-weight:bold}.release{color:var(--green);font-size:12px}.phase-card>p{font-size:13px}.gate{margin-top:17px;border-top:1px solid var(--line);padding-top:14px;font-size:12px;color:var(--muted)}.gate p{margin-bottom:0}.gate strong{color:var(--ink)}.phase-filter{margin-top:19px;border:0;background:none;color:var(--green);padding:0;font-size:12px;font-weight:600}.filters{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:14px;padding:20px;background:#eff4ec;border:1px solid var(--line);border-radius:7px;margin:22px 0}.filters label{font-size:11px;display:block;color:var(--muted);font-weight:600}.filters input,.filters select{display:block;width:100%;margin-top:7px;border:1px solid #cbd8c6;background:white;color:var(--ink);border-radius:4px;padding:10px;font-size:12px}.catalog-top{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:16px}.catalog-top p{margin:0;color:var(--muted);font-size:12px}.catalog-top button{border:1px solid var(--line);border-radius:4px;background:var(--white);padding:8px 13px;font-size:12px;color:var(--green)}.domain{margin:12px 0;border:1px solid var(--line);border-radius:7px;overflow:hidden;background:var(--white)}.domain>summary{padding:16px 18px;cursor:pointer;font-weight:650;font-size:15px;background:#f0f4eb}.feature{border-top:1px solid var(--line)}.feature>summary{list-style:none;display:flex;gap:13px;align-items:center;padding:13px 18px;cursor:pointer;font-size:13px}.feature>summary::-webkit-details-marker{display:none}.feature-id{font:9px var(--mono);color:var(--muted);width:82px;flex-shrink:0}.feature-name{flex:1}.badge{font:10px var(--mono);padding:3px 7px;border-radius:3px;color:var(--green);background:#eff4ec;white-space:nowrap}.feature-body{padding:0 18px 17px 113px;font-size:12px}.feature-body p{margin:8px 0}.feature-body strong{color:var(--ink)}.evidence{color:var(--muted)}.references{display:flex;flex-wrap:wrap;gap:7px 15px;font-size:11px}.empty{padding:25px;border:1px solid var(--line);background:var(--white);border-radius:5px;color:var(--muted)}ol li,ul li{margin-bottom:10px}.source-list{overflow-wrap:anywhere;font-size:11px;columns:2;column-gap:36px}.source-list li{break-inside:avoid}.downloads{display:flex;flex-wrap:wrap;gap:20px;margin:20px 0;font-size:13px}.footnote{font-size:12px;color:var(--muted);padding:25px 0 40px}html{scroll-behavior:smooth}:focus-visible{outline:3px solid #258ac1;outline-offset:3px}@media(max-width:800px){main,header,nav{padding-inline:20px}.phase-grid,.architecture{grid-template-columns:1fr}.filters{grid-template-columns:1fr}.feature>summary{flex-wrap:wrap}.feature-name{min-width:60%;order:1}.feature-id{width:auto}.feature-body{padding-left:18px}.source-list{columns:1}.stat{padding:9px 12px}header{padding-top:35px}nav{gap:15px}.badge{font-size:9px}}@media print{nav,.filters,.catalog-top,.phase-filter,.downloads{display:none}body{background:#fff}header,main{max-width:none;padding:0}.phase-grid,.architecture{display:block}.phase-card,.architecture-node{break-inside:avoid;margin:12px 0}.feature{break-inside:avoid}.feature-body{display:block}.source-list{columns:1}h1{font-size:32px}section{padding:24px 0}}
</style></head><body>
<header><p class="eyebrow">EASI VIEW · PRODUCT AND ENGINEERING PROPOSAL · REVIEWED 13 OCTOBER 2026</p><h1>A capable browser viewer.<br><span>A deliberate path to broad parity.</span></h1><p>Build around EASI JS ingestion, a precise frame and metadata contract, an owned rendering engine and tools, and separately delivered specialty workflows.</p><div class="stats"><div class="stat"><strong>__COUNT__</strong>candidate features</div><div class="stat"><strong>__DOMAINS__</strong>feature domains</div><div class="stat"><strong>__BENCHMARKS__</strong>benchmark families</div><div class="stat"><strong>7</strong>delivery phases</div></div></header>
<nav aria-label="Report navigation"><a href="#recommendation">Architecture</a><a href="#benchmarks">Benchmark</a><a href="#roadmap">Phases</a><a href="#catalog">Full feature catalog</a><a href="#kickoff">First steps</a><a href="#sources">Evidence</a></nav>
<main>
<section id="recommendation"><h2>Recommended architecture</h2><p class="intro">EASI JS provides the ingestion and normalization boundary. Our frame source supplies original scalar samples and geometry to our WebGL2 engine. Our browser workspace composes the independently implemented viewing, tools, and workflow modules.</p><div class="architecture">__ARCH__</div><div class="callout"><p><strong>Zero-footprint:</strong> no installed viewer or browser plugin. Local files can remain entirely on the device; archive, enterprise and optional rendering services can run on servers.</p></div><ul>__PRINCIPLES__</ul><details><summary>Current EASI JS foundation work to prove before broad viewer claims</summary><ul>__GAPS__</ul></details></section>
<section id="benchmarks"><h2>What the benchmark includes</h2><p class="intro">__SCOPE__ Product manuals, conformance references and official documentation were reviewed. Named edition and module differences matter when defining an acceptance test.</p><div class="table-scroll"><table><thead><tr><th>Product family</th><th>Architecture</th><th>Benchmark value and scope</th><th>Evidence</th></tr></thead><tbody>__BENCH_TABLE__</tbody></table></div></section>
<section id="roadmap"><h2>Implementation phases</h2><p class="intro">P1 is a usable 2D alpha. P1 + P2 define the proposed general-viewer 1.0 target. Later phases expand validated capabilities. Phase counts are candidate scope for selected profiles, not a promise to ship every format or specialty immediately.</p><div class="phase-grid">__PHASES__</div></section>
<section id="catalog"><h2>The complete candidate feature catalog</h2><p class="intro">Every entry has a proposed implementation phase, original acceptance criterion and evidence links. The references establish benchmark context; they do not claim universal competitor support or completed easi-view implementation.</p><div class="filters"><label>Search feature, identifier or acceptance criterion<input id="search" type="search" placeholder="Try cine, mammography, pixel, de-identification…"></label><label>Implementation phase<select id="phase"><option value="">All phases</option>__OPTIONS__</select></label><label>Feature domain<select id="category"><option value="">All domains</option>__CATEGORIES__</select></label></div><div class="catalog-top"><p id="count" role="status" aria-live="polite"></p><button id="expand" type="button">Expand all feature details</button></div><div id="feature-list"></div><noscript><p>The searchable catalog needs JavaScript. Open the feature-catalog.json file for every entry and criterion.</p></noscript><div class="downloads"><a href="feature-catalog.json" download>Download the full feature catalog (JSON)</a><a href="proposal.json" download>Download the architecture and roadmap (JSON)</a></div></section>
<section id="kickoff"><h2>The first implementation work package</h2><ol>__KICKOFF__</ol><div class="callout"><p><strong>Recommended first milestone:</strong> EASI-backed CT/MR stacks, calibrated 2D viewing and US cine from local files and one DICOMweb archive, with correct scalar values, cancellation and bounded caches. This proves the foundation that later modules depend on.</p></div></section>
<section id="sources"><h2>Evidence and planning boundaries</h2><ul>__NOTES__</ul><p class="intro">References are primary project, vendor or DICOM-standard sources. Exact product edition, release, licensed module, archive and browser/device support must be recorded when running comparative acceptance tests. Proposed acceptance criteria are original engineering requirements.</p><details><summary>All reference pages (__SOURCE_COUNT__)</summary><ul class="source-list">__SOURCES__</ul></details></section>
<p class="footnote">Local planning artifact · no telemetry, network fetching, or patient images. Generated from the accompanying JSON files.</p>
</main><script type="application/json" id="catalog-data">__DATA__</script><script>
const features=JSON.parse(document.getElementById('catalog-data').textContent);
const list=document.getElementById('feature-list');const search=document.getElementById('search');const phase=document.getElementById('phase');const category=document.getElementById('category');let expanded=false;
function element(tag,className,text){const item=document.createElement(tag);if(className)item.className=className;if(text!==undefined)item.textContent=text;return item;}
function render(){const term=search.value.trim().toLowerCase();const selected=features.filter(f=>(!phase.value||f.phase===phase.value)&&(!category.value||f.category===category.value)&&(!term||[f.id,f.feature,f.category,f.acceptance,f.evidenceNote].join(' ').toLowerCase().includes(term)));list.replaceChildren();document.getElementById('count').textContent=`${selected.length} of ${features.length} candidate features shown`;
const groups=new Map();for(const f of selected){if(!groups.has(f.category))groups.set(f.category,[]);groups.get(f.category).push(f);}if(!selected.length){list.append(element('p','empty','No matching features. Try another search or clear a filter.'));return;}
for(const [name,rows] of groups){const group=element('details','domain');group.open=true;group.append(element('summary','',`${name} · ${rows.length}`));for(const f of rows){const detail=element('details','feature');detail.open=expanded;detail.dataset.featureId=f.id;detail.dataset.phase=f.phase;const summary=element('summary');summary.append(element('span','feature-id',f.id),element('span','feature-name',f.feature),element('span','badge',f.phase),element('span','badge',f.priority));const body=element('div','feature-body');body.append(element('strong','','Acceptance criterion'),element('p','',f.acceptance),element('p','evidence',f.evidenceNote));const refs=element('div','references');for(const [index,url] of f.references.entries()){const a=element('a','',`Reference ${index+1} · ${new URL(url).hostname}`);a.href=url;a.target='_blank';a.rel='noopener noreferrer';refs.append(a);}body.append(refs);detail.append(summary,body);group.append(detail);}list.append(group);}}
search.addEventListener('input',render);phase.addEventListener('change',render);category.addEventListener('change',render);document.getElementById('expand').addEventListener('click',()=>{expanded=!expanded;document.getElementById('expand').textContent=expanded?'Collapse feature details':'Expand all feature details';for(const detail of list.querySelectorAll('.feature'))detail.open=expanded;});for(const button of document.querySelectorAll('.phase-filter'))button.addEventListener('click',()=>{phase.value=button.dataset.phase;category.value='';search.value='';render();document.getElementById('catalog').scrollIntoView({behavior:'smooth'});});render();
</script></body></html>'''
replacements={'COUNT':len(features),'DOMAINS':len(category_counts),'BENCHMARKS':len(p['benchmarks']),'ARCH':architecture,'PRINCIPLES':principles,'GAPS':gaps,'SCOPE':e(p['scope']),'BENCH_TABLE':benchmarks,'PHASES':phases,'OPTIONS':options,'CATEGORIES':category_options,'KICKOFF':kickoff,'NOTES':notes,'SOURCE_COUNT':len(source_urls),'SOURCES':sources,'DATA':data}
for key,value in replacements.items():page=page.replace('__'+key+'__',str(value))
assert '__DATA__' not in page
(root/'easi-view-plan.html').write_text(page)
print(json.dumps({'report':str(root/'easi-view-plan.html'),'features':len(features),'domains':len(category_counts),'benchmarks':len(p['benchmarks']),'sourcePages':len(source_urls),'bytes':len(page.encode())}))
